  21→func TestResolveWorktreeBranch_RegularRepo(t *testing.T) {
  22→	dir := t.TempDir()
  23→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
  24→		dir = resolved
  25→	}
  26→
  27→	_, err := git.PlainInit(dir, false)
  28→	if err != nil {
  29→		t.Fatalf("git init: %v", err)
  30→	}
  31→
  32→	// Read the default branch name directly from HEAD to avoid hard-coding it
  33→	headData, err := os.ReadFile(filepath.Join(dir, ".git", "HEAD"))
  34→	if err != nil {
  35→		t.Fatalf("read HEAD: %v", err)
  36→	}
  37→	wantBranch := strings.TrimPrefix(strings.TrimSpace(string(headData)), "ref: refs/heads/")
  38→
  39→	branch := resolveWorktreeBranch(context.Background(), dir)
  40→	if branch != wantBranch {
  41→		t.Errorf("resolveWorktreeBranch() = %q, want %q", branch, wantBranch)
  42→	}
  43→}
