  45→func TestResolveWorktreeBranch_DetachedHEAD(t *testing.T) {
  46→	dir := t.TempDir()
  47→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
  48→		dir = resolved
  49→	}
  50→
  51→	repo, err := git.PlainInit(dir, false)
  52→	if err != nil {
  53→		t.Fatalf("git init: %v", err)
  54→	}
  55→
  56→	// Create a commit so we can detach HEAD
  57→	wt, err := repo.Worktree()
  58→	if err != nil {
  59→		t.Fatalf("worktree: %v", err)
  60→	}
  61→	testFile := filepath.Join(dir, "test.txt")
  62→	if err := os.WriteFile(testFile, []byte("hello"), 0o644); err != nil {
  63→		t.Fatalf("write file: %v", err)
  64→	}
  65→	if _, err := wt.Add("test.txt"); err != nil {
  66→		t.Fatalf("add: %v", err)
  67→	}
  68→	hash, err := wt.Commit("initial", &git.CommitOptions{
  69→		Author: &object.Signature{
  70→			Name:  "Test",
  71→			Email: "test@test.com",
  72→			When:  time.Now(),
  73→		},
  74→	})
  75→	if err != nil {
  76→		t.Fatalf("commit: %v", err)
  77→	}
  78→
  79→	// Detach HEAD by writing the raw hash to .git/HEAD
  80→	headPath := filepath.Join(dir, ".git", "HEAD")
  81→	if err := os.WriteFile(headPath, []byte(hash.String()+"\n"), 0o644); err != nil {
  82→		t.Fatalf("write HEAD: %v", err)
  83→	}
  84→
  85→	branch := resolveWorktreeBranch(context.Background(), dir)
  86→	if branch != "HEAD" {
  87→		t.Errorf("resolveWorktreeBranch() = %q, want %q for detached HEAD", branch, "HEAD")
  88→	}
  89→}
