  91→func TestResolveWorktreeBranch_WorktreeGitFile(t *testing.T) {
  92→	// Simulate a worktree where .git is a file pointing to a gitdir
  93→	dir := t.TempDir()
  94→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
  95→		dir = resolved
  96→	}
  97→
  98→	// Create a fake gitdir with a HEAD file
  99→	gitdir := filepath.Join(dir, "fake-gitdir")
 100→	if err := os.MkdirAll(gitdir, 0o755); err != nil {
 101→		t.Fatalf("mkdir gitdir: %v", err)
 102→	}
 103→	headPath := filepath.Join(gitdir, "HEAD")
 104→	if err := os.WriteFile(headPath, []byte("ref: refs/heads/feature-branch\n"), 0o644); err != nil {
 105→		t.Fatalf("write HEAD: %v", err)
 106→	}
 107→
 108→	// Create a worktree-style .git file
 109→	worktreeDir := filepath.Join(dir, "worktree")
 110→	if err := os.MkdirAll(worktreeDir, 0o755); err != nil {
 111→		t.Fatalf("mkdir worktree: %v", err)
 112→	}
 113→	gitFile := filepath.Join(worktreeDir, ".git")
 114→	if err := os.WriteFile(gitFile, []byte("gitdir: "+gitdir+"\n"), 0o644); err != nil {
 115→		t.Fatalf("write .git file: %v", err)
 116→	}
 117→
 118→	branch := resolveWorktreeBranch(context.Background(), worktreeDir)
 119→	if branch != "feature-branch" {
 120→		t.Errorf("resolveWorktreeBranch() = %q, want %q", branch, "feature-branch")
 121→	}
 122→}
