 469→
 470→	// Session started 15m ago with no LastInteractionTime should NOT show "active" in stats
 471→	for _, line := range lines {
 472→		if strings.Contains(line, "Cursor") {
 473→			if strings.Contains(line, "active") {
 474→				t.Errorf("Session without LastInteractionTime should not show 'active', got: %s", line)
