 476→		}
 477→	}
 478→
 479→	// Should contain per-session token counts
 480→	if !strings.Contains(output, "tokens 1.2k") {
 481→		t.Errorf("Expected per-session 'tokens 1.2k' for first session (800+400), got: %s", output)
 482→	}
 483→
 484→	// Should contain aggregate footer with session count (no total tokens in footer)
