 487→	}
 488→
 489→	// Should NOT contain phase indicators (removed)
 490→	if strings.Contains(output, "● active") || strings.Contains(output, "● idle") || strings.Contains(output, "● ended") {
 491→		t.Errorf("Output should not contain phase indicators, got: %s", output)
 492→	}
 493→
 494→	// Should NOT contain file counts (removed)
 495→	if strings.Contains(output, "files ") {
 496→		t.Errorf("Output should not contain file counts, got: %s", output)
